xml.Script:
        clGreen  := '50A020';
        clYellow := 'FFFF00';
        clRed    := 'FF0000';
        clBlue   := '000096';
        clBlack  := '333333';

        K := 0.6;

        ang := 2 * Pi / 7;
        s2  := sqrt(2);


        include 'Figures\Scripts\Vectors.inc';

        // calc axes
        Ax[1] := 1/s2; Ay[1] :=-1/s2; Az[1] := 0;
        Ax[2] := 1;    Ay[2] := 0;    Az[2] := 0;

        VectorRotatePoint( Ax[2], Ay[2], Az[2],  Ax[1], Ay[1], Az[1],  2*Pi * 3 / 7, True); // Axis 0
        Ax[0] := Ans_X; Ay[0] := Ans_Y; Az[0] := Ans_Z;
        VectorRotatePoint( Ax[1], Ay[1], Az[1],  Ax[2], Ay[2], Az[2], -2*Pi * 3 / 7, True); // Axis 3
        Ax[3] := Ans_X; Ay[3] := Ans_Y; Az[3] := Ans_Z;

        // calc axis (MX, MY, MZ) and angle of global symmetry
        VectorNormalToPlane( Ax[0], Ay[0], Az[0], Ax[1], Ay[1], Az[1], Ax[2], Ay[2], Az[2]);
        MX := Ans_X; MY := Ans_Y; MZ := Ans_Z;
        GAngle := VectorRotatingAngle( MX, MY, MZ, Ax[2], Ay[2], Az[2],  Ax[1], Ay[1], Az[1])); // near but not equal 2*Pi/7

        procedure CalcSymmetricVector(Angl); // find normal vector that after turning around axis 1 on Angle then around axis 2 on Angle returns back to itself
        begin
            VectorRotatePoint( 0, 0, 1,  1, 0, 0, -Angl / 2, False);
            X1 := Ans_X; Y1 := Ans_Y; Z1 := Ans_Z;
            VectorRotatePoint( 0, 0, 1,  1,-1, 0,  Angl / 2, True);
            X2 := Ans_X; Y2 := Ans_Y; Z2 := Ans_Z;
            VectorMultiply( X1, Y1, Z1,  X2, Y2, Z2);
            VectorNormalize( Ans_X, Ans_Y, Ans_Z);
        end;

        // calc side's cut plane
        CalcSymmetricVector( 2*Pi / 7);
        PX := Ans_X; PY := Ans_Y; PZ := Ans_Z; // normalized vector where red and yellow region touch (to find point: * D2)

        D1 := PX * K; // axes cut depth

        D2 := K; // face cut depth

        CalcSymmetricVector( 4*Pi / 7);
        D3 := Ans_X * K / VectorScalarMultiply( PX, PY, PZ,  Ans_X, Ans_Y, Ans_Z); // back side cut depth

        VectorRotatePoint( PX, PY, PZ,  1, 0, 0,  Pi / 7, False);
        D4 := K * (PX - Ans_Y / cos(Pi / 7)) / s2; // facet cit depth

